package cl.acis.catalogos.controller;
import cl.acis.catalogos.config.ActorHeaders; import cl.acis.catalogos.dto.*; import cl.acis.catalogos.model.TipoFoto; import cl.acis.catalogos.service.FotoService; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.constraints.NotNull; import org.springframework.core.io.Resource; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.*;
@RestController @RequestMapping("/api/fotos") public class FotoController{final FotoService s;final ActorHeaders h;public FotoController(FotoService x,ActorHeaders a){s=x;h=a;}@PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) FotoResponse subir(@RequestPart("archivo")MultipartFile archivo,@RequestParam Long ordenId,@RequestParam TipoFoto tipo,@RequestParam(required=false)Double latitud,@RequestParam(required=false)Double longitud,HttpServletRequest q){ActorHeaders.Actor a=h.leer(q);h.exigir(a,"ADMINISTRADOR","JEFATURA","TECNICO");return s.subir(archivo,ordenId,tipo,a.id(),latitud,longitud);}@GetMapping("/orden/{ordenId}") List<FotoResponse> listar(@PathVariable Long ordenId,HttpServletRequest q){h.leer(q);return s.listar(ordenId);}@GetMapping("/{id}/archivo") ResponseEntity<Resource> archivo(@PathVariable Long id,HttpServletRequest q){h.leer(q);return ResponseEntity.ok().contentType(MediaType.IMAGE_JPEG).body(s.archivo(id));}@DeleteMapping("/{id}") ResponseEntity<Void> borrar(@PathVariable Long id,HttpServletRequest q){ActorHeaders.Actor a=h.leer(q);h.exigir(a,"ADMINISTRADOR","JEFATURA");s.borrar(id);return ResponseEntity.noContent().build();}}
